import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function readPageFile(e){return readFileSync(resolve(__dirname,"../../frontend/padma-bhushan-explorer",e),"utf-8")}function readLandingFile(){return readFileSync(resolve(__dirname,"../../frontend/awards-of-india-explorer/index.html"),"utf-8")}describe("Padma Bhushan Explorer — Page Structure",()=>{let e;beforeAll(()=>{e=readPageFile("index.html")}),it("contains hero title and badge info",()=>{expect(e).toContain('class="pb-hero-title"'),expect(e).toContain("Padma Bhushan Explorer"),expect(e).toContain("Third-Highest Civilian Honour")}),it("contains all required content sections",()=>{["history","eligibility","medal-design","selection","award-fields","awardees","timeline","facts","gallery"].forEach(t=>{expect(e).toContain(`id="${t}"`),expect(e).toContain(`data-tab="${t}"`)})}),it("contains notable awardees",()=>{expect(e).toContain("Homi J. Bhabha"),expect(e).toContain("M. S. Subbulakshmi"),expect(e).toContain("Sundar Pichai"),expect(e).toContain("Satya Nadella")}),it("links shared stylesheet, page stylesheet, and script",()=>{expect(e).toContain('href="../../styles.css"'),expect(e).toContain('href="style.css"'),expect(e).toContain('src="script.js"')})}),describe("Padma Bhushan Explorer — Assets & Script",()=>{it("includes a non-empty stylesheet",()=>{const e=readPageFile("style.css");expect(e.length).toBeGreaterThan(1e3),expect(e).toContain(".pb-hero")}),it("includes valid interactive script",()=>{const e=readPageFile("script.js");expect(e).toContain("initTabs")})}),describe("Padma Bhushan Explorer — Landing Page Integration",()=>{it("is linked on the Awards of India Explorer Landing Page",()=>{const e=readLandingFile();expect(e).toContain("Padma Bhushan"),expect(e).toContain("../padma-bhushan-explorer/index.html")})});